import{_ as i}from"./chunks/gnoblin-waybar-settings.K8pY60zE.js";import{_ as e,o as a,c as t,a2 as n}from"./chunks/framework.BfI5QxtK.js";const g=JSON.parse('{"title":"Try Gnoblin in a window","description":"","frontmatter":{},"headers":[],"relativePath":"devkit.md","filePath":"devkit.md"}'),l={name:"devkit.md"};function h(d,s,o,p,r,c){return a(),t("div",null,[...s[0]||(s[0]=[n('<h1 id="try-gnoblin-in-a-window" tabindex="-1">Try Gnoblin in a window <a class="header-anchor" href="#try-gnoblin-in-a-window" aria-label="Permalink to &quot;Try Gnoblin in a window&quot;">​</a></h1><p>The devkit runs a nested Gnoblin session inside your Wayland desktop. Use it to test a build without logging out.</p><p>First complete the <a href="./install-source">source build</a>.</p><h2 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h2><p>From the checkout:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/install&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><p>A desktop viewer and terminal open. Programs started from that terminal connect to the nested compositor.</p><p>To choose a terminal explicitly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/install&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kitty</span></span></code></pre></div><h2 id="try-your-shell" tabindex="-1">Try your shell <a class="header-anchor" href="#try-your-shell" aria-label="Permalink to &quot;Try your shell&quot;">​</a></h2><p>From the devkit terminal, launch an installed layer-shell client:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">waybar</span></span></code></pre></div><p>The bar should appear inside the viewer. Try its menus and launcher. Close the terminal to stop the devkit.</p><p><img src="'+i+`" alt="GNOME Settings beneath Waybar in a clean Gnoblin devkit session"></p><p><em>The devkit can run stock desktop apps alongside independently launched shell clients.</em></p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Accepted value</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>MONITOR</code></td><td><code>WIDTHxHEIGHT</code>, in pixels</td><td><code>1600x900</code></td><td>Sets the virtual display size</td></tr><tr><td><code>GNOME_DEVKIT_HEADLESS</code></td><td><code>1</code> or unset</td><td>Unset</td><td>Starts without a viewer when set to <code>1</code></td></tr><tr><td><code>GNOME_DEVKIT_EXEC</code></td><td>Shell command string, or unset</td><td>Unset</td><td>Runs the command instead of opening a terminal</td></tr><tr><td><code>GNOME_DEVKIT_UNSAFE_MODE</code></td><td><code>0</code>, <code>1</code>, or unset</td><td>Unset</td><td>Enables privileged Eval only when set to <code>1</code></td></tr></tbody></table><p>These are environment variables read when the devkit starts. For example, <code>MONITOR=1280x800</code> selects a 1280 by 800 virtual display. The unsafe mode is intended only for an isolated test process.</p><h2 id="headless-scripting-mode" tabindex="-1">Headless / scripting mode <a class="header-anchor" href="#headless-scripting-mode" aria-label="Permalink to &quot;Headless / scripting mode&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOME_DEVKIT_HEADLESS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOME_DEVKIT_EXEC=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;gnoblinctl feature list --json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_PREFIX=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/install&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><p>This runs without a host Wayland display and exits after the command. <code>just test-preview</code> checks this environment.</p><h2 id="isolation" tabindex="-1">Isolation <a class="header-anchor" href="#isolation" aria-label="Permalink to &quot;Isolation&quot;">​</a></h2><p>The nested display and D-Bus bus are separate. Host X11, accessibility and gvfs connections are not passed through.</p><p><strong>Your HOME and runtime directory remain real.</strong> Applications can still read or change your files and configuration. This is not a security sandbox.</p><p>For a fresh profile, including screenshots and demos, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-clean-devkit.sh</span></span></code></pre></div><p>This creates disposable home, config, data, cache, state and runtime directories and removes them when the devkit closes. The viewer still connects to your host Wayland session and may use its PipeWire socket. Use a VM when the guest must be fully separate from host services. Check the image before publishing it.</p><h3 id="documentation-captures" tabindex="-1">Documentation captures <a class="header-anchor" href="#documentation-captures" aria-label="Permalink to &quot;Documentation captures&quot;">​</a></h3><p>The checked-in documentation scenes can be recaptured with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> waybar-firefox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> waybar-launcher</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_DOC_BINGUX_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">../bingux/shell/bingux</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bingux-firefox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickshell-firefox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> waybar-files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> waybar-settings</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> waybar-mako-notification</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_DOC_BINGUX_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">../bingux/shell/bingux</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bingux-files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickshell-files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/capture-doc-examples.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> window-effects</span></span></code></pre></div><p>Each capture uses a disposable profile and removes it afterward. Scenes pair Firefox and stock GNOME apps with Waybar + Mako, Quickshell and Bingux. Bingux is one separate shell project using Gnoblin.</p><p>The Mako scene shows a Calendar reminder over Firefox. Firefox opens GNOME Help in a fresh profile; set <code>GNOBLIN_DOC_FIREFOX_URL</code> to use another page. Network access is needed for the default page.</p><p>Captures need a visible Wayland session, a current build in <code>./install</code>, and the scene&#39;s apps. The build must include Adwaita Hyprcursor. The live cursor is included in each image; the capture contains only the devkit viewport.</p><p>The <a href="./testing">private test harness</a> is for automated checks. A devkit run does not verify the installed login session.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Next step</th></tr></thead><tbody><tr><td>No host <code>WAYLAND_DISPLAY</code></td><td>Use a Wayland desktop or headless mode</td></tr><tr><td>No Shell in <code>./install</code></td><td>Finish the source build</td></tr><tr><td>No terminal found</td><td>Install one or pass its command explicitly</td></tr><tr><td>Quickshell/Qt mismatch</td><td>Install or rebuild a matching Quickshell</td></tr><tr><td><code>EBUSY</code> taking the session</td><td>Use this devkit launcher, not a direct native/KMS launch</td></tr></tbody></table>`,36)])])}const F=e(l,[["render",h]]);export{g as __pageData,F as default};
